import { NgModule } from '@angular/core';
import { PreloadAllModules, RouterModule, Routes } from '@angular/router';
import { BoatlayoutComponent } from './layout/boatowner/boatlayout/boatlayout.component';
import { LayoutauthComponent } from './layout/auth/layoutauth.component';
import { LandinglayoutComponent } from './layout/landing/landinglayout/landinglayout.component';
import { Page404Component } from './page404/page404.component';
import { externalUrlProvider } from './services/services.service';

const routes: Routes = [
  {
    path: '',
    component: LandinglayoutComponent,
    children: [
      { path: '', loadChildren: () => import('./landingpage/landingpage.module').then(m => m.LandingpageModule) },
      { path: '', loadChildren: () => import('./profile/profile.module').then(m => m.ProfileModule) },
    ]
  },
  {
    path: '',
    component: LandinglayoutComponent,
    children: [
      { path: '', loadChildren: () => import('./landingpage/landingpage.module').then(m => m.LandingpageModule) },
    ]
  },
  {
    path: '',
    component: BoatlayoutComponent,
    children: [
      { path: '', loadChildren: () => import('./boatowner/boatowner.module').then(m => m.BoatownerModule) },
      { path: '', loadChildren: () => import('./tours/tours.module').then(m => m.ToursModule) },
      { path: '', loadChildren: () => import('./booking/booking.module').then(m => m.BookingModule) },
    ]
  },
  {
    path: '',
    component: LayoutauthComponent,
    children: [
      { path: '', loadChildren: () => import('./auth/auth.module').then(m => m.AuthModule) },
    ]
  },
  { path: 'externalRedirect', resolve: { url: externalUrlProvider, }, component: LandinglayoutComponent, },
  { path: '**', component: Page404Component }
];

@NgModule({
  imports: [
    RouterModule.forRoot(routes, { preloadingStrategy: PreloadAllModules, onSameUrlNavigation: 'reload', })
  ],
  exports: [RouterModule]
})
export class AppRoutingModule { }
