import {
  Component,
  OnInit,
  ChangeDetectionStrategy
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router, RouterLink, NavigationEnd } from '@angular/router';
import { LayoutService } from '../../layout.service';
import { Users } from 'godigital-lib';

import { BehaviorSubject, combineLatest, Observable } from 'rxjs';
import { filter, map, shareReplay, startWith } from 'rxjs/operators';

type SiteMode =
  | 'guest-global'
  | 'guest-owner'
  | 'customer-global'
  | 'customer-owner'
  | 'owner-dashboard';

type PrefixState = { isPrefixed: boolean; urlPrefix: string | null };

type FooterVM = {
  user: Users | null;
  isLoggedIn: boolean;
  isBoatOwner: boolean;
  urlPrefix: string | null;
  isPrefixed: boolean;
  mode: SiteMode;
};

@Component({
  selector: 'app-landingfooter',
  standalone: true,
  imports: [CommonModule, RouterLink],
  templateUrl: './landingfooter.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LandingfooterComponent implements OnInit {

  year = new Date().getFullYear();

  /** prefix state */
  private readonly prefix$ = new BehaviorSubject<PrefixState>({
    isPrefixed: false,
    urlPrefix: null
  });

  /** url state */
  private url$!: Observable<string>;

  /** user state */
  private user$!: Observable<Users | null>;

  /** derived view model (used in HTML) */
  public vm$!: Observable<FooterVM>;

  constructor(
    private router: Router,
    public layoutSvc: LayoutService
  ) {}

  ngOnInit(): void {
    // url stream
    this.url$ = this.router.events.pipe(
      filter((ev): ev is NavigationEnd => ev instanceof NavigationEnd),
      map(() => this.router.url || ''),
      startWith(this.router.url || ''),
      shareReplay({ bufferSize: 1, refCount: true })
    );

    // user stream
    this.user$ = this.layoutSvc.mainSvc.getUser().pipe(
      startWith(null),
      shareReplay({ bufferSize: 1, refCount: true })
    );

    // view model stream
    this.vm$ = combineLatest([this.user$, this.url$, this.prefix$]).pipe(
      map(([user, url, pref]) => {
        const isLoggedIn = !!user;

        const role = (user?.role ?? '').toString().trim().toLowerCase();
        const isBoatOwner = ['boatowner', 'boat_owner', 'owner'].includes(role);

        const onOwnerDashboard = url.startsWith('/owner') || url.startsWith('/host');

        const mode: SiteMode =
          (onOwnerDashboard && isLoggedIn && isBoatOwner)
            ? 'owner-dashboard'
            : (!isLoggedIn
                ? (pref.isPrefixed ? 'guest-owner' : 'guest-global')
                : (pref.isPrefixed ? 'customer-owner' : 'customer-global'));

        return {
          user,
          isLoggedIn,
          isBoatOwner,
          urlPrefix: pref.urlPrefix,
          isPrefixed: pref.isPrefixed,
          mode
        };
      }),
      shareReplay({ bufferSize: 1, refCount: true })
    );

    // initial prefix detection
    this.prefix$.next(this.detectPrefix());
  }

  private detectPrefix(): PrefixState {
    if (typeof window === 'undefined') {
      return { isPrefixed: false, urlPrefix: null };
    }

    const host = window.location.host;
    const parts = host.split('.');

    if (host.includes('localhost') || host.includes('127.0.0.1')) {
      const params = new URLSearchParams(window.location.search);
      const p = params.get('prefix');
      return p ? { isPrefixed: true, urlPrefix: p } : { isPrefixed: false, urlPrefix: null };
    }

    if (parts.length === 2) return { isPrefixed: false, urlPrefix: null };

    if (parts.length >= 3) {
      const sub = parts[0].toLowerCase();
      if (sub === 'www' || sub === 'app') return { isPrefixed: false, urlPrefix: null };
      return { isPrefixed: true, urlPrefix: sub };
    }

    return { isPrefixed: false, urlPrefix: null };
  }

  // navigation helpers
  goToHelp(): void { this.router.navigate(['/help']); }
  goToAbout(): void { this.router.navigate(['/about-platform']); }
  goToContact(): void { this.router.navigate(['/contactus']); }
  goToHostInfo(): void { this.router.navigate(['/owner/start']); }
  goToBookings(): void { this.router.navigate(['/bookings']); }
  goToOwnerRevenues(): void { this.router.navigate(['/owner/revenues']); }
  goToDashboardHelp(): void { this.router.navigate(['/owner/help']); }
}
