import {
  Component,
  OnInit,
  OnDestroy,
  Input,
  OnChanges,
  SimpleChanges
} from '@angular/core';
import { ActivatedRoute, Router, NavigationEnd } from '@angular/router';
import { filter, Subscription } from 'rxjs';

import { LayoutService } from '../../layout.service';   // or BoatsService
import { USERROLE, Users } from 'godigital-lib';

@Component({
  selector: 'app-boatheader',
  templateUrl: './boatheader.component.html'
})
export class BoatheaderComponent implements OnInit, OnDestroy, OnChanges {

  /** Optional: parent can pass mainpageId directly */
  @Input() mainpageId?: string;

  user?: Users | null;
  avatarUrl?: string;
  isOwner = false;
  isHostingView = false;

  // Brand / mainpage context
  brandLabel = 'Boatify';
  isOwnerMainpage = false;

  // For [routerLink] & [queryParams]
  homeLinkCommands: any[] = ['/home'];
  homeLinkQueryParams: any = null;

  private subs = new Subscription();

  constructor(
    public layoutSvc: LayoutService,
    private router: Router,
    private route: ActivatedRoute
  ) {}

  ngOnInit(): void {
    // Logged user
    this.subs.add(
      this.layoutSvc.mainSvc.getUser().subscribe(u => {
        this.user = u;
        this.avatarUrl = u?.photoURL || undefined;
        this.isOwner = u?.role === USERROLE.OWNER || u?.role === USERROLE.ADMIN;
      })
    );

    this.isHostingView = this.layoutSvc.isHostingView ?? false;

    // Recompute context on navigation
    this.subs.add(
      this.router.events
        .pipe(filter(e => e instanceof NavigationEnd))
        .subscribe(() => this.resolveMainpageContext())
    );

    // Initial
    this.resolveMainpageContext();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if ('mainpageId' in changes) {
      this.resolveMainpageContext();
    }
  }

  ngOnDestroy(): void {
    this.subs.unsubscribe();
  }

  // ----------------------------------------------------------------
  // MAINPAGE CONTEXT RESOLUTION
  // ----------------------------------------------------------------

  private resolveMainpageContext(): void {
    // 1) If parent explicitly passes mainpageId, use it
    let effectiveId = this.mainpageId || '';

    // 2) If not provided, try query param or subdomain
    if (!effectiveId) {
      effectiveId = this.detectMainpageIdFromQueryOrSubdomain() || '';
    }

    if (effectiveId) {
      const { id, slug } = this.normalizeMainpageId(effectiveId);

      this.isOwnerMainpage = true;
      this.brandLabel = this.toTitleCase(slug);

      // We want /mainpage?mainpage=<slug>
      this.homeLinkCommands = ['/mainpage'];
      this.homeLinkQueryParams = { mainpage: slug };

      this.mainpageId = id;  // store normalized id
    } else {
      // Global Boatify context
      this.isOwnerMainpage = false;
      this.brandLabel = 'Boatify';
      this.homeLinkCommands = ['/home'];
      this.homeLinkQueryParams = null;
      this.mainpageId = undefined;
    }
  }

  /**
   * Find mainpage:
   *   - ?mainpage=layali  OR ?mainpage=owner-home-layali
   *   - subdomain layali.boatify.com
   */
  private detectMainpageIdFromQueryOrSubdomain(): string | null {
    // 1) query param
    const qp = this.route.snapshot.queryParamMap;
    let main = qp.get('mainpage');

    // 2) subdomain
    if (!main && typeof window !== 'undefined') {
      const host = window.location.hostname; // layali.boatify.com
      const parts = host.split('.');

      if (parts.length > 2) {
        const sub = parts[0];
        if (sub && sub !== 'www' && sub !== 'localhost') {
          main = sub;
        }
      }
    }

    return main;
  }

  /**
   * Accepts:
   *   "layali"            -> { id: "owner-home-layali", slug: "layali" }
   *   "owner-home-layali" -> { id: "owner-home-layali", slug: "layali" }
   */
  private normalizeMainpageId(raw: string): { id: string; slug: string } {
    const trimmed = raw.trim();
    const lower = trimmed.toLowerCase();

    if (lower.startsWith('owner-home-')) {
      const slug = lower.substring('owner-home-'.length);
      return { id: lower, slug };
    }

    // plain slug
    return {
      id: `owner-home-${lower}`,
      slug: lower
    };
  }

  private toTitleCase(slug: string): string {
    if (!slug) return '';
    return slug
      .split('-')
      .filter(Boolean)
      .map(w => w.charAt(0).toUpperCase() + w.slice(1))
      .join(' ');
  }

  // ----------------------------------------------------------------
  // Existing helpers
  // ----------------------------------------------------------------

  toggleHostingMode(): void {
    this.isHostingView = !this.isHostingView;
    this.layoutSvc.isHostingView = this.isHostingView;
  }

  onAvatarError(evt: Event): void {
    (evt.target as HTMLImageElement).style.display = 'none';
  }

  logout(): void {
    this.layoutSvc.logout();
  }
}
