import { Component, OnDestroy, OnInit } from '@angular/core';
import { Router, RouterLink, RouterOutlet } from '@angular/router';
import { LayoutService } from '../../layout.service'; // whatever your real path is
import { NgIf, AsyncPipe, NgClass } from '@angular/common';
import { FormsModule } from '@angular/forms';

import { StoreDbService } from 'godigital-lib'; // adjust path if needed
import firebase from 'firebase/compat/app';
import { Subscription } from 'rxjs';

@Component({
  selector: 'app-landinglayout',
  standalone: true,
  imports: [
    RouterLink,
    RouterOutlet,
    NgIf,
    AsyncPipe,
    NgClass,
    FormsModule
  ],
  templateUrl: './landinglayout.component.html'
})
export class LandinglayoutComponent implements OnInit, OnDestroy {

  user: firebase.User | null = null;
  private authSub?: Subscription;

  // 🔍 Header search state
  headerMode: 'boat' | 'experience' = 'boat';
  headerLocation = '';
  headerDate = '';
  headerPeople: number | null = null;
  headerExperienceType = '';

  // Example experience types (EVJF = bachelorette party in FR)
  experienceTypes = [
    'Afterwork at sea',
    'EVJF / Bachelorette',
    'Birthday',
    'Sunset cruise',
    'Corporate event',
    'Romantic outing',
    'Other'
  ];

  constructor(
    public layoutSvc: LayoutService,
    public storeDb: StoreDbService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.authSub = this.storeDb.authState$.subscribe(user => {
      this.user = user;
    });
  }

  ngOnDestroy(): void {
    this.authSub?.unsubscribe();
  }

  get isLoggedIn(): boolean {
    return !!this.user;
  }

  // TODO: real owner detection
  get isBoatOwner(): boolean {
    return false;
  }

  // 🚤 Rent your boat CTA
  goToOwnerCta() {
    if (this.isBoatOwner) {
      this.router.navigate(['/owner/tours']);
    } else {
      this.router.navigate(['/boat-owners/onboarding']);
    }
  }

  // 🔍 Search handler
  headerSearch() {
    const queryParams: any = {
      mode: this.headerMode
    };

    if (this.headerLocation) queryParams.location = this.headerLocation;
    if (this.headerDate) queryParams.date = this.headerDate;
    if (this.headerPeople) queryParams.people = this.headerPeople;

    if (this.headerMode === 'experience' && this.headerExperienceType) {
      queryParams.experienceType = this.headerExperienceType;
    }

    this.router.navigate(['/tours/search'], { queryParams });
  }

  async logout() {
    if (this.storeDb.auth) {
      try {
        await this.storeDb.auth.signOut();
      } catch (e) {
        console.error('Error while logging out', e);
      }
    }
  }
}
