// header.component.ts
import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router, RouterLink } from '@angular/router';

import { LayoutService } from '../../layout.service';   // 🚨 adjust path if needed
import { Users } from 'godigital-lib';             // type matching your JSON

type SiteMode =
  | 'guest-global'        // 1) Guest, no prefix
  | 'guest-owner'         // 2) Guest, owner subdomain
  | 'customer-global'     // 3) Logged-in customer, no prefix
  | 'customer-owner'      // 4) Logged-in customer, owner subdomain
  | 'owner-dashboard';    // 5) Boat owner dashboard mode

@Component({
  selector: 'app-landingheader',
  standalone: true,
  imports: [CommonModule, RouterLink],
  templateUrl: './landingheader.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LandingheaderComponent implements OnInit {

  // --- user info ---
  user: Users | null = null;
  isLoggedIn = false;
  isBoatOwner = false;

  // --- domain / prefix ---
  urlPrefix: string | null = null;   // e.g. "layali"
  isPrefixed = false;

  // --- current mode ---
  mode: SiteMode = 'guest-global';

  // --- UI ---
  avatarUrl?: string;

  constructor(
    public layoutSvc: LayoutService,   // has mainSvc.getUser()
    private router: Router,
    private cdr: ChangeDetectorRef
  ) {}

  ngOnInit(): void {
    this.detectPrefix();

    // Subscribe to auth changes
    this.layoutSvc.mainSvc.getUser().subscribe((u: Users | null) => {
      this.user = u;
      this.isLoggedIn = !!u;

      // 🔎 isBoatOwner based on user.role string
      const role = u?.role?.toLowerCase?.() || '';
      this.isBoatOwner = ['boatowner', 'boat_owner', 'owner'].includes(role);

      this.avatarUrl = u?.photoURL || undefined;

      this.computeMode();
      this.cdr.markForCheck();
    });

    // recompute mode on route changes (for owner dashboard vs customer mode)
    this.router.events.subscribe(() => {
      this.computeMode();
      this.cdr.markForCheck();
    });
  }

  // ------------------ PREFIX DETECTION ------------------

  private detectPrefix(): void {
    const host = window.location.host;    // e.g. "boatify.com", "layali.boatify.com", "localhost:4200"
    const parts = host.split('.');

    // Local dev: use ?prefix=layali if you want
    if (host.includes('localhost') || host.includes('127.0.0.1')) {
      const params = new URLSearchParams(window.location.search);
      const p = params.get('prefix');
      if (p) {
        this.isPrefixed = true;
        this.urlPrefix = p;
      } else {
        this.isPrefixed = false;
        this.urlPrefix = null;
      }
      return;
    }

    if (parts.length === 2) {
      // e.g. boatify.com
      this.isPrefixed = false;
      this.urlPrefix = null;
    } else if (parts.length >= 3) {
      const sub = parts[0].toLowerCase();
      if (sub === 'www' || sub === 'app') {
        this.isPrefixed = false;
        this.urlPrefix = null;
      } else {
        // e.g. layali.boatify.com
        this.isPrefixed = true;
        this.urlPrefix = sub;
      }
    }
  }

  // ------------------ MODE COMPUTATION ------------------

  private computeMode(): void {
    const url = this.router.url || '';
    const onOwnerDashboard = url.startsWith('/owner') || url.startsWith('/host');

    if (onOwnerDashboard && this.isLoggedIn && this.isBoatOwner) {
      this.mode = 'owner-dashboard';
      return;
    }

    if (!this.isLoggedIn) {
      // guest
      this.mode = this.isPrefixed ? 'guest-owner' : 'guest-global';
      return;
    }

    // logged-in customer (maybe also boat owner)
    this.mode = this.isPrefixed ? 'customer-owner' : 'customer-global';
  }

  // ------------------ NAV HELPERS ------------------

  // Global customer/guest
  goToGlobalBoats(): void {
    this.router.navigate(['/search'], { queryParams: { type: 'boats' } });
  }

  // Owner-prefixed public pages
  goToOwnerBoats(): void {
    if (!this.urlPrefix) return;
    this.router.navigate(['/', this.urlPrefix, 'boats']);
  }

  goToOwnerExperiences(): void {
    if (!this.urlPrefix) return;
    this.router.navigate(['/', this.urlPrefix, 'experiences']);
  }

  goToOwnerNews(): void {
    if (!this.urlPrefix) return;
    this.router.navigate(['/', this.urlPrefix, 'news']);
  }

  // Owner dashboard
  goToOwnerDashboardToday(): void {
    this.router.navigate(['/owner/today']);
  }

  // Switch modes
  goToCustomerMode(): void {
    // from owner dashboard back to “customer” view
    if (this.isPrefixed && this.urlPrefix) {
      this.router.navigate(['/', this.urlPrefix]);
    } else {
      this.router.navigate(['/']);
    }
  }

  goToBoatOwnerMode(): void {
    // from customer to owner dashboard
    this.router.navigate(['/owner/today']);
  }

  // ------------------ AUTH ACTIONS ------------------

  login(): void {
    this.router.navigate(['/login']);
  }

  signup(): void {
    this.router.navigate(['/signup']);
  }

  hostYourBoat(): void {
    this.router.navigate(['/owner/start']);
  }

  logout(): void {
    // adjust to your actual logout method if name differs
    if (this.layoutSvc.logout) {
      this.layoutSvc.logout();
    } else {
      // fallback: navigate to logout route if you have one
      this.router.navigate(['/logout']);
    }
  }
}
